// === ESTRUCTURA DEL PATRÓN BUILDER ===

// 1. Producto — el objeto complejo
class House {
  constructor(
    public walls: string,
    public roof: string,
    public windows: number,
    public doors: number,
    public garage: boolean
  ) {}

  describe() {
    console.log(`Casa con ${this.walls}, techo ${this.roof}, ${this.windows} ventanas`);
  }
}

// 2. Interfaz Builder
interface HouseBuilder {
  setWalls(type: string): this;
  setRoof(type: string): this;
  setWindows(count: number): this;
  setDoors(count: number): this;
  setGarage(has: boolean): this;
  build(): House;
}

// 3. Builder Concreto
class ConcreteHouseBuilder implements HouseBuilder {
  private house: Partial<House> = {};

  setWalls(type: string) { this.house.walls = type; return this; }
  setRoof(type: string) { this.house.roof = type; return this; }
  setWindows(count: number) { this.house.windows = count; return this; }
  setDoors(count: number) { this.house.doors = count; return this; }
  setGarage(has: boolean) { this.house.garage = has; return this; }

  build(): House {
    return new House(
      this.house.walls ?? 'concrete',
      this.house.roof ?? 'tile',
      this.house.windows ?? 4,
      this.house.doors ?? 2,
      this.house.garage ?? false
    );
  }
}

// 4. Director — receta predefinida
class HouseDirector {
  static buildLuxuryHouse(builder: HouseBuilder): House {
    return builder
      .setWalls('marble')
      .setRoof('slate')
      .setWindows(12)
      .setDoors(6)
      .setGarage(true)
      .build();
  }
}

// Uso:
const builder = new ConcreteHouseBuilder();
const house = HouseDirector.buildLuxuryHouse(builder);
house.describe();

